#include "OriginalGameCar.h"
#include <fstream>
#include <cstring>
namespace source=r3d::game::originalrace::source;
float value(unsigned u){float f;std::memcpy(&f,&u,4);return f;}unsigned word(float f){unsigned u;std::memcpy(&u,&f,4);return u;}
int main(int argc,char**argv){if(argc!=3)return 2;std::ifstream input(argv[1]);std::ofstream out(argv[2]);unsigned id,speed,steer,maximum;while(input>>id>>speed>>steer>>maximum){source::GameCar car;source::GameCar::MotorDescription m;m.maximumTorque=m.restBrakeTorque=m.brakeTorque=0;car.ConfigureMotor(m);source::GameCar::DynamicsDescription d;d.maximumSteerAngle=value(maximum);d.steerRotation=value(1078530011U);std::vector<source::GameCar::WheelDynamics>wheels;for(int i=0;i<4;++i){source::GameCar::WheelDynamics w;w.positionX=i<2?1.F:-1.F;w.steering=w.driven=i<2;w.radius=.5F;wheels.push_back(w);}car.BindWheels(std::vector<bool>(4,false),std::vector<bool>(4,false));car.ConfigureDynamics(d,wheels);source::GameCar::FixedStepInput in;in.manualSteering=true;in.steering=value(steer);source::GameCar::FixedStepState state;state.signedSpeed=value(speed);state.absoluteSpeed=state.horizontalSpeed=state.signedSpeed<0?-state.signedSpeed:state.signedSpeed;state.anyWheelContact=state.drivenWheelContact=state.firstDrivenWheelContact=state.allWheelContact=true;auto c=car.OnFixedStepDrive(1.F/60,in,state);out<<"{\"case\":"<<id<<",\"speed_word\":"<<word(car.GetSpeed())<<",\"yaw_word\":"<<word(c.steeringYaw)<<",\"visual_word\":"<<word(c.steeringAngle)<<"}\n";}return input.eof()&&out.good()?0:3;}
